H = "Hakeem Force Academy"
QS = [
(H, "In Surah Al-Muzzammil, by what word is the Prophet (PBUH) addressed?", ["Al-Muddaththir", "Al-Muzzammil (the one wrapped in garments)", "Ya Ayyuhan-Nas", "Ya Ayyuhal-Kafirun"], 1, "The surah opens with Ya ayyuhal-Muzzammil, meaning O you who are wrapped up in garments. This is how Allah addresses the Prophet (PBUH) there.", "Surah Al-Muddaththir, which follows it, opens with a similar address meaning the one covered with a cloak.", [1475]),
(H, "What is the meaning of the word 'accomplish'?", ["To fail", "To achieve or complete successfully", "To delay", "To ignore"], 1, "To accomplish something means to complete it or achieve it successfully. Its synonyms are achieve and fulfil.", "A common antonym of accomplish is fail.", [2978]),
(H, "What is the closest meaning of 'accomplished' when used for a person?", ["Unskilled", "Skilled or highly talented", "Careless", "Lazy"], 1, "As an adjective, accomplished describes a person who is highly skilled or talented, such as an accomplished pianist.", "As a verb form, accomplished also means achieved or completed.", [2807, 3165]),
(H, "What is the meaning of 'admonished'?", ["Praised warmly", "Warned or firmly reprimanded", "Ignored", "Rewarded"], 1, "To admonish someone is to warn or scold them firmly. Reprimand and rebuke are its synonyms.", "The noun form is admonition, meaning a warning.", [2979, 3164]),
(H, "In which year was the present Constitution of Pakistan adopted?", ["1956", "1962", "1973", "1985"], 2, "The National Assembly passed the present Constitution on 10 April 1973 and it came into force on 14 August 1973.", "It was suspended during the martial laws of 1977 and 1999 and restored later.", [2200]),
(H, "Which part of speech describes or modifies a verb?", ["Object", "Subject", "Adverb", "Noun"], 2, "An adverb tells us how, when, where or how much an action happens. So it describes a verb.", "An adverb can also modify an adjective or another adverb.", [2526, 2547]),
(H, "An aeroplane flies in the air mainly because of which force?", ["Lift", "Friction", "Gravity", "Magnetism"], 0, "The curved wings make air move faster over the top, creating lower pressure above and an upward force called lift. Lift must be greater than or equal to weight to fly.", "The four forces on an aeroplane are lift, weight, thrust and drag.", [663]),
(H, "Choose the correct word: The aeroplane flew ___ my head.", ["on", "over", "at", "with"], 1, "The preposition over is used when something passes above a person or object. The other options do not suit the meaning.", "Over means above, while across means from one side to the other.", [2406, 2407]),
(H, "On which side of Pakistan is Afghanistan situated?", ["East", "South", "West and north-west", "North-east"], 2, "Afghanistan lies along the western and north-western border of Pakistan. India is to the east and China to the north-east.", "The Pakistan-Afghanistan border is called the Durand Line.", [433]),
(H, "Which famous pass connects Pakistan and Afghanistan?", ["Bolan Pass", "Khyber Pass", "Karakoram Pass", "Lowari Pass"], 1, "The Khyber Pass links Peshawar in Pakistan with Jalalabad in Afghanistan. It has been an ancient trade and invasion route.", "Torkham is the main border crossing at the Khyber Pass.", [992]),
(H, "At what age did Hazrat Muhammad (SAW) receive prophethood?", ["25 years", "30 years", "40 years", "63 years"], 2, "The Prophet (SAW) received the first revelation in the Cave of Hira at the age of 40.", "The first revealed verses were from Surah Al-Alaq.", [1424]),
(H, "The International Civil Aviation Organization (ICAO) is a specialized agency of which organization?", ["NATO", "United Nations", "European Union", "OIC"], 1, "ICAO was created in 1944 by the Chicago Convention and became a UN specialized agency in 1947.", "ICAO is headquartered in Montreal, Canada.", [2418]),
(H, "Which companion narrated the largest number of ahadith?", ["Hazrat Abu Hurairah (RA)", "Hazrat Umar (RA)", "Hazrat Ali (RA)", "Hazrat Uthman (RA)"], 0, "Hazrat Abu Hurairah (RA) is reported to have narrated about 5374 ahadith, the most of any companion.", "Hazrat Aisha (RA) and Ibn Umar (RA) are also among the major narrators.", [1225]),
(H, "At which session of the All India Muslim League was the Lahore Resolution passed?", ["25th session", "26th session", "27th session", "28th session"], 2, "The Lahore Resolution was passed at the 27th annual session of the All India Muslim League, held at Lahore from 22 to 24 March 1940.", "The resolution was moved by A. K. Fazlul Huq on 23 March 1940.", [667]),
(H, "Who is the Supreme Commander of the Pakistan Air Force, as of October 2026?", ["The Chief of the Air Staff", "The Prime Minister", "The President of Pakistan", "The Chief Justice"], 2, "Under Article 243 of the Constitution, the supreme command of the armed forces is vested in the President. As of 2026 the President is Asif Ali Zardari.", "Field Marshal Asim Munir became the first Chief of Defence Forces in December 2025 after the 27th Amendment.", [4242]),
(H, "An aircraft uses 80 gallons of fuel to travel 540 km. About how much fuel is needed for 700 km?", ["About 93.3 gallons", "About 103.7 gallons", "About 110 gallons", "About 120 gallons"], 1, "Fuel per km is 80 divided by 540. For 700 km: 80 x 700 / 540 = 56000 / 540 = about 103.7 gallons.", "Fuel use is directly proportional to distance when the rate is constant.", [1888]),
(H, "Ali is younger than Akram, and Usman is older than Ali. Who is the youngest of the three?", ["Akram", "Usman", "Ali", "Cannot be determined"], 2, "Akram is older than Ali, and Usman is older than Ali. So Ali is younger than both.", "The relation between Akram and Usman is unknown, but it does not matter here.", [1393]),
(H, "Who was Ali Bogra in Pakistan's history?", ["The first Governor General", "Prime Minister of Pakistan (1953 to 1955)", "The first Chief Justice", "The first Army Chief"], 1, "Muhammad Ali Bogra served as the third Prime Minister of Pakistan from 1953 to 1955. He earlier served as ambassador to the USA.", "He was succeeded as Prime Minister by Chaudhry Muhammad Ali.", [4314]),
(H, "What is the meaning of the idiom 'once for all'?", ["Again and again", "Finally, for the last time", "Sometimes", "Never"], 1, "Once for all (also once and for all) means finally and permanently, so it need not be done again.", "Idioms must be learnt as a whole, as their meaning is not the sum of the words.", [2920]),
(H, "What is the meaning of the phrase 'all and sundry'?", ["Only a few people", "Everyone, without exception", "Nobody", "Only experts"], 1, "All and sundry means everyone, whoever they may be.", "Sundry on its own means various or several.", [2981]),
(H, "Who was the first president of the Indian National Congress when it was formed in 1885?", ["A. O. Hume", "W. C. Bonnerjee", "Dadabhai Naoroji", "Gopal Krishna Gokhale"], 1, "Womesh Chunder Bonnerjee presided over the first session held in Bombay in December 1885.", "A. O. Hume, a retired British official, was the founder and first general secretary.", [4409]),
(H, "In which surah of the Holy Quran does Allah take an oath by time?", ["Surah Al-Asr", "Surah Al-Fil", "Surah Al-Ikhlas", "Surah Al-Kawthar"], 0, "Surah Al-Asr begins with Wal-Asr, which means by the time. It then says that mankind is in loss except the believers who do good deeds.", "Surah Al-Asr is the 103rd surah and has 3 verses.", [792]),
(H, "Under the Indus Waters Treaty, how many rivers is Pakistan allowed to use as its main share?", ["Two", "Three", "Four", "Six"], 1, "The three western rivers, Indus, Jhelum and Chenab, were given to Pakistan. The three eastern rivers, Ravi, Beas and Sutlej, went to India.", "The treaty was signed in 1960 with World Bank mediation.", [1354]),
(H, "Find the next term in the series: a1, b3, c5, ?", ["d6", "d7", "e7", "d9"], 1, "The letters go a, b, c, d in order. The numbers go 1, 3, 5, 7, increasing by 2, so the next term is d7.", "Odd numbers form an arithmetic series with common difference 2.", [2387]),
]
